entries[411925] = { ["name"] = "Strahl der Pein", ["text"] = "Unbegrenzte Reichweite\nSofort\nKazzara beschwört Fragmente lodernder Energie, die aus Schreckensrisse n herausbrechen. Jedes Fragment entzündet einen lodernden Strahl, jagt einen Spielercharakter in der Nähe und hinterlässt eine ' Geschmolzene Narbe '. Bei Berührung fügt der Strahl Spielercharakteren alle 0.3 Sek. 167127 Schattenflammenschaden zu." }
