entries[412044] = { ["name"] = "Temposchlitzen", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Zaubernde greift aus mehreren Zeitlinien heraus gleichzeitig an, wodurch sein Nahkampftempo 8 Sek. lang um 100% erhöht wird.\n\nJeder erfolgreiche Schlag löst ein Echo aus einer weiteren Zeitlinie aus und erhöht den erlittenen Schaden des Ziels um 15%. Dieser Effekt ist stapelbar." }
entries[412045] = { ["name"] = "Instabile Essenz", ["text"] = "Unbegrenzte Reichweite\nSofort\nThadrion erfüllt Spielercharaktere mit instabiler Energie, die alle 2 Sek. 3 Arkanschaden verursacht und mit der Zeit an Intensität gewinnt.\n\nBei Entfernung verschmilzt die Energie kurzzeitig und explodiert dann, was Spielercharakteren innerhalb von 12 Metern 60 Arkanschaden zufügt und ein Vorkommen von ' Unberechenbarer Überrest ' hinterlässt.\n\nEine verbleibende Spur der Energie springt dann auf einen Spielercharakter in der Nähe über und belegt ihn mit 'Instabile Essenz'." }
